"""Day-seven reasoning pilot: one transfer, four different questions."""
from author_remaining import topic, W3


def interactive(slug, title, ids, body, interaction, ref, limit):
    item = topic(slug, title, ids, body, [], ref, limit)
    item['interaction'] = interaction
    return item


